package io.knowledgebrain.brainquery;
import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class RecordNetworkProjectionTest {
 @Test void persistedFiveKindSnapshotsReadWithoutResetOrPrimitiveDefaultsForNewKinds(){var json=tools.jackson.databind.json.JsonMapper.builder().build();var entity=id();var n=new BrainProjection.Input(id(),entity,id(),"CONCEPT",1,"ACTIVE","PRIVATE","Legacy","Body",List.of(),"a".repeat(32));var tree=(tools.jackson.databind.node.ObjectNode)json.valueToTree(n);tree.remove("recordVersion");tree.remove("aggregateId");assertEquals(n,BrainProjectionStore.snapshot(json,json.writeValueAsString(tree)));tree.put("kind","BOOKMARK_CONCEPTS");assertThrows(RuntimeException.class,()->BrainProjectionStore.snapshot(json,json.writeValueAsString(tree)));}
 UUID id(){return BrainProjectionIntegrationTest.id();}
 io.knowledgebrain.contracts.content.recordconcepts.v1.RecordConceptEventEnvelopeV1 links(String kind){var p=io.knowledgebrain.contracts.content.recordconcepts.v1.RecordConceptsChangedPayloadV1.newBuilder().setAssociationId(id().toString()).setRecordId(id().toString()).setRecordType(kind).setVersion(8).setRecordVersion(2).setRecordState("ACTIVE").setRevisionId(id().toString()).addLinks(io.knowledgebrain.contracts.content.recordconcepts.v1.RecordConceptLinkV1.newBuilder().setLinkId(id().toString()).setConceptId(id().toString())).build();return io.knowledgebrain.contracts.content.recordconcepts.v1.RecordConceptEventEnvelopeV1.newBuilder().setEventId(id().toString()).setProducer("content-service").setAggregateType("RecordConceptLinks").setAggregateId(p.getAssociationId()).setSpaceId(id().toString()).setActorId(id().toString()).setOccurredAtEpochMillis(1).setTraceId("a".repeat(32)).setEventVersion(1).setEventType("RecordConceptsChanged").setPayload(p.toByteString()).build();}
 @Test void associationTransportKeyRemainsAssociationIdWhileTypedProjectionUsesSourceId()throws Exception{for(var kind:BrainProjection.RECORDS){var e=links(kind);var p=io.knowledgebrain.contracts.content.recordconcepts.v1.RecordConceptsChangedPayloadV1.parseFrom(e.getPayload());var h=Map.of("id",e.getEventId(),"schema_group","content","schema_artifact","record-concepts-events","schema_version","1","trace_id",e.getTraceId());var n=BrainProjection.decode("content.record-concepts.v1",e.toByteArray(),e.getAggregateId(),h);assertEquals(kind,n.owner());assertEquals(p.getRecordId(),n.entityId().toString());assertEquals(8,n.version());assertEquals(2,n.recordVersion());assertEquals("RECORD_CONCEPT",n.refs().getFirst().role());assertThrows(IllegalArgumentException.class,()->BrainProjection.decode("content.record-concepts.v1",e.toByteArray(),p.getRecordId(),h));}}
 @Test void associationRejectsDuplicateTargetsRetiredSnapshotsAndUnknownKinds()throws Exception{var e=links("BOOKMARK");var p=io.knowledgebrain.contracts.content.recordconcepts.v1.RecordConceptsChangedPayloadV1.parseFrom(e.getPayload());for(var bad:List.of(p.toBuilder().addLinks(p.getLinks(0)).build(),p.toBuilder().setRecordType("NOTE").build(),p.toBuilder().setRecordState("RETIRED").build(),p.toBuilder().setRecordVersion(0).build()))assertThrows(IllegalArgumentException.class,()->BrainProjection.decode("content.record-concepts.v1",e.toBuilder().setPayload(bad.toByteString()).build().toByteArray()));}
 @Test void frozenBookmarkContractRejectsForeignVisibilityAndStripsRetiredBody(){var record=id();var p=io.knowledgebrain.contracts.content.bookmark.v1.BookmarkChangedPayloadV1.newBuilder().setBookmarkId(record.toString()).setRevisionId(id().toString()).setVersion(1).setState("ACTIVE").setVisibility("PRIVATE").setTitle("Saved").setUrl("https://example.test/").setMemo("MemoOnly").setCreatedAt("2026-10-18T00:00:00Z").setUpdatedAt("2026-10-18T00:00:00Z").build();var e=io.knowledgebrain.contracts.content.bookmark.v1.BookmarkEventEnvelopeV1.newBuilder().setEventId(id().toString()).setProducer("content-service").setAggregateType("Bookmark").setAggregateId(record.toString()).setSpaceId(id().toString()).setActorId(id().toString()).setOccurredAtEpochMillis(java.time.Instant.parse(p.getUpdatedAt()).toEpochMilli()).setTraceId("a".repeat(32)).setEventVersion(1).setEventType("BookmarkCreated").setPayload(p.toByteString()).build();assertTrue(BrainProjection.decode("content.bookmark.v1",e.toByteArray()).body().contains("MemoOnly"));assertThrows(IllegalArgumentException.class,()->BrainProjection.decode("content.bookmark.v1",e.toBuilder().setPayload(p.toBuilder().setVisibility("PUBLIC").build().toByteString()).build().toByteArray()));var retired=e.toBuilder().setEventType("BookmarkRetired").setPayload(p.toBuilder().setVersion(2).setState("RETIRED").build().toByteString()).build();assertEquals("",BrainProjection.decode("content.bookmark.v1",retired.toByteArray()).body());}
}
